window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[349]={"id":"349","numero":349,"titre":"Infection aiguë des parties molles","objectifs":[{"id":"349-1","rang":"A","rubrique":"Définition","titre":"Connaître les principales infections des parties molles","contenu":"<p><span class=\"kw-clinique\">Les</span> infections aiguës des parties molles regroupent les infections du <span class=\"kw-clinique\">doigt</span> et de la <span class=\"kw-clinique\">main</span>, dont la sémiologie est dictée par l'<span class=\"kw-def\">anatomie</span>. On les classe selon la <strong>structure atteinte</strong>.</p>\n      <table >\n        <thead><tr><th>Structure atteinte</th><th>Entité</th></tr></thead>\n        <tbody>\n          <tr><td>Région péri-unguéale</td><td><span class=\"kw-def\">Périonyxis</span> (paronychie)</td></tr>\n          <tr><td>Pulpe et ses cloisons conjonctives</td><td><span class=\"kw-def\">Panaris pulpaire</span></td></tr>\n          <tr><td>Gaine synoviale des fléchisseurs</td><td><span class=\"kw-def\">Phlegmon des gaines</span></td></tr>\n          <tr><td>Tissu cellulaire sous-cutané</td><td><span class=\"kw-def\">Cellulite</span> (<span class=\"kw-clinique\">panaris</span> sous-cutané)</td></tr>\n          <tr><td>Articulation</td><td><span class=\"kw-alerte\">Arthrite</span></td></tr>\n          <tr><td>Os</td><td><span class=\"kw-alerte\">Ostéite</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Trois grands cadres cliniques</strong></p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Formes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Panaris</strong></span></td><td>périonyxis (paronychie aiguë) ; <span class=\"kw-clinique\">panaris</span> sous-cutané (<span class=\"kw-clinique\">cellulite</span>)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Abcès</strong></span></td><td><span class=\"kw-clinique\">abcès</span> sous-cutané ; <span class=\"kw-clinique\">abcès</span> de la main (espaces profonds) ; <span class=\"kw-clinique\">panaris</span> pulpaire</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Phlegmon</strong></span></td><td><span class=\"kw-clinique\">phlegmon</span> des gaines (ténosynovite)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Anatomie = piège.</strong> Comme le visage, la main <span class=\"kw-clinique\">résiste bien aux infections</span> grâce à sa riche vascularisation, mais elle est très exposée (contacts). Du fait des cloisonnements anatomiques, une infection peut <span class=\"kw-alerte\">très vite se cloisonner</span> et mimer un <span class=\"kw-clinique\">abcès</span>, poussant à la <span class=\"kw-ttt\">chirurgie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 155 — Infection cutanéo-muqueuse</em></p>","frequence":0},{"id":"349-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'un abcès, d'un panaris, d'un phlegmon des gaines et de la main","contenu":"<p>Quatre définitions à connaître <strong>au mot près</strong> (QCM ⭐⭐⭐⭐) : elles reposent sur la présence ou non d'une <span class=\"kw-def\">cavité néoformée</span> et sur la structure atteinte.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th><th>Caractéristique clé</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Abcès</strong></span></td>\n            <td>collection de <span class=\"kw-clinique\">pus dans une cavité néoformée</span>, conséquence de l'extension d'une infection de voisinage</td>\n            <td>délimité par une <span class=\"kw-bio\">membrane pyogénique</span> ; poche circonscrite</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Panaris</strong></span></td>\n            <td>terme général = <span class=\"kw-clinique\">« infection du doigt »</span> (pulpe ou péri-unguéale), en pratique souvent réduit au <span class=\"kw-def\">périonyxis</span></td>\n            <td>infection aiguë <span class=\"kw-clinique\">superficielle</span> des parties molles d'un doigt</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Phlegmon des gaines</strong></span></td>\n            <td>infection de la <span class=\"kw-clinique\">gaine synoviale des fléchisseurs</span> (ténosynovite) — la « <strong><span class=\"kw-clinique\">péritonite</span> du doigt</strong> »</td>\n            <td>présence de <span class=\"kw-alerte\">liquide dans la gaine</span> ; <strong>pas</strong> dans une cavité néoformée (≠ <span class=\"kw-clinique\">abcès</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Phlegmon</strong></span> (général)</td>\n            <td>infection <span class=\"kw-clinique\">diffuse</span> du tissu conjonctif <strong>sans</strong> collection purulente organisée</td>\n            <td>propagation rapide possible dans <span class=\"kw-clinique\">les</span> gaines synoviales</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Le mot qui sépare tout.</strong> <span class=\"kw-def\">Abcès</span> = cavité <strong>néoformée</strong> avec membrane pyogénique. <span class=\"kw-alerte\">Phlegmon des gaines</span> = liquide dans une cavité <strong>préexistante</strong> (la gaine synoviale). <span class=\"kw-def\">Cellulite / phlegmon diffus</span> = <strong>pas</strong> de collection organisée.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « principales infections des parties molles »</em></p>","frequence":4},{"id":"349-3","rang":"A","rubrique":"Épidémiologie","titre":"Connaître la bactérie la plus souvent responsable","contenu":"<p><span class=\"kw-clinique\">Les</span> infections des parties molles sont <span class=\"kw-clinique\">monobactériennes dans 3/4 des cas</span>. Deux germes dominent.</p>\n      <table >\n        <thead><tr><th>Germe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Staphylococcus aureus</strong></span> <span class=\"kw-chiffre\">(≈ 60 %)</span></td>\n            <td>bactérie <strong>la plus souvent isolée</strong> quel que soit le tableau (portage nasal physiologique) ; souches à <span class=\"kw-alerte\">leucocidine de Panton-Valentine</span> → <span class=\"kw-clinique\">nécrose</span> purulente cutanée (± pneumopathie nécrosante)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Streptocoques</strong></span> <span class=\"kw-chiffre\">(≈ 10 %)</span></td>\n            <td><em>S. pyogenes</em> (SGA β-hémolytique) : <span class=\"kw-ttt\">toujours sensible à l'amoxicilline</span> ; toxines (hyaluronidase, streptokinase) → <span class=\"kw-alerte\">nécrose tissulaire en quelques heures</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Germe selon la présentation</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Staphylocoque doré</span> : germe le plus fréquent des <span class=\"kw-clinique\">périonyxis aigus</span> et du <span class=\"kw-clinique\">phlegmon des gaines</span></li>\n        <li><span class=\"kw-etio\">SGA</span> : germe le plus souvent en cause dans le <span class=\"kw-clinique\">panaris sous-cutané</span> (<span class=\"kw-clinique\">cellulite</span>)</li>\n      </ul>\n      <p><strong>Autres bactéries</strong> : BGN ; <span class=\"kw-etio\">Pasteurella multocida</span>, <span class=\"kw-etio\">Capnocytophaga</span> (exclusivement après morsure animale) ; mycobactéries (<em>M. marinum</em> : eau d'aquarium, cultures prolongées).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 155 — Infection cutanéo-muqueuse</em></p>","frequence":0},{"id":"349-4","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les spécificités microbiologiques des morsures","contenu":"<p>La flore buccale animale et humaine est <span class=\"kw-clinique\">polymicrobienne</span> : toute morsure est une <span class=\"kw-alerte\">plaie profonde infectée</span>, <span class=\"kw-alerte\">urgence</span> médico-chirurgicale.</p>\n      <table >\n        <thead><tr><th></th><th>Chien</th><th>Chat</th><th>Humain</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Communs</strong></td><td colspan=\"3\"><span class=\"kw-etio\">Streptococcus sp.</span>, <span class=\"kw-etio\">Staphylococcus aureus</span>, <span class=\"kw-etio\">anaérobies</span></td></tr>\n          <tr><td><strong>Spécifique</strong></td><td><span class=\"kw-etio\">Pasteurella multocida</span> ; <span class=\"kw-alerte\">Capnocytophaga canimorsus</span> ; <em>Eikenella corrodens</em></td><td><span class=\"kw-etio\">Pasteurella multocida</span> ; <span class=\"kw-etio\">Bartonella henselae</span> ; Capnocytophaga</td><td><span class=\"kw-etio\">Eikenella corrodens</span> <span class=\"kw-chiffre\">(7-30 %)</span> ; <em><span class=\"kw-etio\">Haemophilus</span> influenzae</em></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Deux germes à retenir.</strong> <span class=\"kw-etio\">Pasteurella multocida</span> (chien/chat) justifie le traitement par <span class=\"kw-ttt\">cyclines</span> (<span class=\"kw-ttt\">doxycycline</span>) chez l'adulte ; <span class=\"kw-alerte\">Capnocytophaga canimorsus</span> = <span class=\"kw-def\">mortalité</span> quasi constante chez l'<span class=\"kw-alerte\">immunodéprimé / splénectomisé</span> (<span class=\"kw-alerte\">purpura fulminans</span>).</div>\n      <p><strong>Risque <span class=\"kw-etio\">infectieux</span></strong> : morsure de <span class=\"kw-clinique\">chat</span> infectée dans <span class=\"kw-chiffre\">50 %</span> des cas (dents fines, lésions profondes faussement rassurantes) > morsure de chien (peu infectante mais <span class=\"kw-chiffre\">75 %</span> des morsures). Morsure humaine : ≈ 42 bactéries différentes ; <span class=\"kw-alerte\">plaie de la face dorsale d'une MCP</span> (coup de poing) = <span class=\"kw-alerte\">arthrite jusqu'à preuve du contraire</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> et indications d'<span class=\"kw-alerte\">hospitalisation</span> » · objectif « PEC médico-chirurgicale d'un <span class=\"kw-clinique\">abcès</span> et d'un <span class=\"kw-clinique\">panaris</span> »</em></p>","frequence":0},{"id":"349-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le mode d'inoculation","contenu":"<p>L'infection cutanée fait suite à une <span class=\"kw-def\">inoculation septique directe</span> après brèche cutanée, le plus souvent <span class=\"kw-clinique\">méconnue</span> (piqûre). La main, richement vascularisée, résiste bien aux infections mais est très exposée (contacts).</p>\n      <p><strong>Deux modes d'inoculation</strong></p>\n      <table >\n        <thead><tr><th>Mode</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Inoculation directe / primitive</strong></span></td><td>plaie pénétrante (objet tranchant, écharde), <span class=\"kw-clinique\">morsure</span>, geste post-opératoire</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Inoculation secondaire</strong></span></td><td>extension d'un foyer septique local de voisinage (<span class=\"kw-clinique\">panaris</span>, <span class=\"kw-clinique\">cellulite</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Inoculation iatrogène</strong></span></td><td><span class=\"kw-clinique\">abcès</span> post-chirurgical, injection sous-cutanée / articulaire → <span class=\"kw-etio\">streptocoques</span> (groupe <em>milleri</em>) ou BGN</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Séquence évolutive de la <span class=\"kw-etio\">colonisation</span></strong></p>\n      <ul>\n        <li>Contamination d'une plaie par <span class=\"kw-clinique\">les</span> germes (<span class=\"kw-chiffre\">plaie non suturée après 6 h</span>)</li>\n        <li><span class=\"kw-etio\">Colonisation</span> des structures voisines</li>\n        <li>Constitution d'une infection (<span class=\"kw-chiffre\">après 24 h</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Facteurs conditionnant l'extension.</strong> Rapport (inconnu) entre <span class=\"kw-clinique\">type, quantité et virulence des germes</span> d'une part, et <span class=\"kw-clinique\">moyens de défense</span> locaux (vascularisation) et généraux (immunité) de l'autre.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « bactérie la plus souvent responsable » · objectif « quatre phases évolutives »</em></p>","frequence":0},{"id":"349-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les terrains à risque","contenu":"<p>Il faut distinguer <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">terrains à risque</span> (qui aggravent le <span class=\"kw-def\">pronostic</span>) des <span class=\"kw-def\">facteurs favorisants</span> (qui facilitent l'infection ou masquent le tableau).</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Terrain à risque</strong></span></td>\n            <td><span class=\"kw-clinique\">toxicomanie IV</span> ; <span class=\"kw-clinique\">diabète déséquilibré</span> ; <span class=\"kw-clinique\">immunodépression</span> (<span class=\"kw-ttt\">immunosuppresseurs</span>, <span class=\"kw-etio\">VIH</span>, déficit immunitaire, cancer)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Facteurs favorisants</strong></span></td>\n            <td><span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">corticoïdes</span> ; <span class=\"kw-ttt\">tabac</span> (↓ afflux sanguin, ↓ apport des ATB, prédispose à la <span class=\"kw-clinique\">nécrose</span>) ; <span class=\"kw-ttt\">ATB à l'aveugle</span> sans parage (chronicisation : atténue <span class=\"kw-clinique\">les</span> signes sans guérir)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Immunodéprimé.</strong> Toute infection peut engager le <span class=\"kw-alerte\">pronostic vital</span> ; présence classique de BGN, <span class=\"kw-clinique\">évolution</span> lente, gestes d'excision répétés, taux d'<span class=\"kw-alerte\">amputation digitale 20-60 %</span>. Toxicomane IV : risque de <span class=\"kw-alerte\">dermo-hypodermite nécrosante</span> et d'<span class=\"kw-clinique\">abcès</span> dorsal à <span class=\"kw-bio\">SARM</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> et indications d'<span class=\"kw-alerte\">hospitalisation</span> »</em></p>","frequence":0},{"id":"349-7","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les quatre phases évolutives","contenu":"<p>Le développement d'une infection des parties molles obéit à un <span class=\"kw-def\">cycle évolutif constant</span> en <strong>quatre phases</strong>. La distinction <span class=\"kw-clinique\">réversible</span> / <span class=\"kw-alerte\">irréversible</span> commande la décision thérapeutique.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>1. Phase d'invasion</strong></span></td>\n            <td><span class=\"kw-clinique\">asymptomatique</span> ; sélection des germes pathogènes (<em>S. aureus</em>, <em>S. pyogenes</em>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>2. Phase phlegmasique</strong></span></td>\n            <td>douleur intense <strong>non insomniante</strong> ; signes inflammatoires locaux (rougeur, chaleur, <span class=\"kw-clinique\">œdème</span>), <strong>pas de <span class=\"kw-clinique\">fièvre</span></strong> ; <span class=\"kw-ttt\">réversible, accessible au traitement médical</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>3. Stade de collection</strong></span></td>\n            <td>douleur <span class=\"kw-alerte\">pulsatile et insomniante</span> ; signes régionaux (lymphangite, <span class=\"kw-clinique\">adénopathie</span>) et généraux (<span class=\"kw-clinique\">fièvre</span>) possibles ; <strong>irréversible</strong> → impose la <span class=\"kw-ttt\">mise à plat chirurgicale</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>4. Stade de diffusion / complications</strong></span></td>\n            <td>locales (fistulisation, <span class=\"kw-clinique\">cellulite</span>, phlegmon, arthrite, ostéite) ; régionales (lymphangite, adénite) ; générales (<span class=\"kw-alerte\">bactériémie</span> : <span class=\"kw-clinique\">fièvre</span>, frissons)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Le tournant.</strong> Le passage <span class=\"kw-clinique\">phlegmasique</span> → <span class=\"kw-alerte\">collecté</span> fait basculer du traitement médical au traitement <strong>chirurgical</strong> : la douleur devient <span class=\"kw-alerte\">pulsatile et insomniante</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « complications <span class=\"kw-clinique\">les</span> plus fréquentes »</em></p>","frequence":0},{"id":"349-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications les plus fréquentes","contenu":"<p>En l'absence de traitement adéquat, l'infection diffuse selon <strong>trois niveaux</strong> (local, régional, général). Certaines complications sont propres à chaque entité.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Périonyxis</span> (paronychie)</td><td><span class=\"kw-clinique\">abcès</span> pulpaire, <span class=\"kw-clinique\">phlegmon</span>, <span class=\"kw-clinique\">panaris « en bouton de chemise »</span></td></tr>\n          <tr><td><span class=\"kw-def\">Panaris sous-cutané</span></td><td>extension aux tissus plus profonds</td></tr>\n          <tr><td><span class=\"kw-def\">Abcès sous-cutané</span></td><td><span class=\"kw-clinique\">nécrose</span> de la peau pulpaire ; extension (<span class=\"kw-clinique\">phlegmon</span> des gaines, arthrite, ostéite)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Phlegmon des gaines</span></td><td><span class=\"kw-alerte\">nécrose tendineuse</span> avec fistulisation ; <span class=\"kw-alerte\">phlegmon à bascule</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Complications communes (par niveau de diffusion)</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Locales profondes</span> : <span class=\"kw-clinique\">cellulite</span>, phlegmon, <span class=\"kw-alerte\">arthrite</span>, <span class=\"kw-alerte\">ostéite</span></li>\n        <li><span class=\"kw-clinique\">Régionales</span> : lymphangite, adénite (épitrochléenne et axillaire)</li>\n        <li><span class=\"kw-alerte\">Générales</span> : <span class=\"kw-clinique\">bactériémie</span> (<span class=\"kw-clinique\">fièvre</span>, frissons)</li>\n        <li><span class=\"kw-alerte\">Dermo-hypodermite nécrosante</span> (<span class=\"kw-alerte\">fasciite nécrosante</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Complications tardives.</strong> Dystrophie unguéale, <span class=\"kw-clinique\">raideur</span>, séquelles fonctionnelles, récidive. L'enjeu d'un <span class=\"kw-def\">diagnostic précoce</span> est d'éviter des séquelles sur l'<strong>outil indispensable qu'est la main</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 155 — Infection cutanéo-muqueuse</em></p>","frequence":0},{"id":"349-9","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir reconnaître un abcès ou un panaris","contenu":"<p>Le diagnostic est <span class=\"kw-def\">purement clinique</span> : <strong>aucun examen complémentaire</strong> n'est nécessaire dans <span class=\"kw-clinique\">les</span> formes classiques. La distinction <span class=\"kw-clinique\">phlegmasique</span> (médical) / <span class=\"kw-alerte\">collecté</span> (chirurgical) est la clé.</p>\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Panaris</span> — <span class=\"kw-clinique\">les</span> stades</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Phlegmasique</strong></span> (non collecté)</td><td>douleur modérée, <span class=\"kw-clinique\">diurne</span>, sensation de cuisson ; <span class=\"kw-clinique\">tuméfaction</span> érythémateuse à limites floues ; <strong>pas de collection, pas de pulsatilité, apyrexie</strong></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Collecté</strong></span></td><td>douleur <span class=\"kw-alerte\">intense, lancinante, PULSATILE, insomniante</span> ; petite <span class=\"kw-clinique\">masse</span> <span class=\"kw-clinique\">rénitente</span> (collection sous tension) ; signes inflammatoires ± diffusion régionale</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Formes cliniques de <span class=\"kw-clinique\">panaris</span></strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Périonyxis</span> (paronychie / <span class=\"kw-clinique\">panaris</span> sous-unguéal) : le plus fréquent (onychophagie, manucure) ; <span class=\"kw-etio\">staphylocoque</span> doré</li>\n        <li><span class=\"kw-def\">Panaris anthracoïde</span> : <span class=\"kw-clinique\">furoncle</span> d'un poil digital (dos de P1), <span class=\"kw-ttt\">excision obligatoire</span></li>\n        <li><span class=\"kw-alerte\">Panaris « en bouton de chemise »</span> : bipolaire, péri-unguéal communiquant à la pulpe par un pertuis — à ne pas méconnaître (incision incomplète)</li>\n        <li><span class=\"kw-def\">Panaris sous-cutané</span> (<span class=\"kw-clinique\">cellulite</span>) : <span class=\"kw-clinique\">érythème</span> diffus, pulpe <span class=\"kw-etio\">inflammatoire</span> <strong>souple</strong> (pas tendue), <strong>pas encore d'<span class=\"kw-clinique\">abcès</span></strong> → pas de <span class=\"kw-ttt\">ponction</span></li>\n      </ul>\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Abcès</span> — la collection</h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Reconnaissance</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Abcès sous-cutané</strong></span></td><td><span class=\"kw-clinique\">cellulite</span> avec en son centre une collection : zone érythémateuse indurée et chaude, <span class=\"kw-clinique\">tuméfaction</span> <span class=\"kw-clinique\">rénitente, molle, fluctuante</span> ; <span class=\"kw-clinique\">porte d'entrée souvent retrouvée</span> ; <span class=\"kw-ttt\">ponction</span> possible</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Abcès profond</strong></span> (espaces de la main)</td><td>éminences thénar / hypothénar / médio-palmaire / interdigital ; difficile à distinguer du sous-cutané → <span class=\"kw-imagerie\">échographie</span> confirme</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Panaris pulpaire</strong></span></td><td><span class=\"kw-clinique\">abcès</span> de la pulpe : doigt <span class=\"kw-alerte\">pulsatile</span> et <strong>tendu</strong> (≠ souple du <span class=\"kw-clinique\">panaris</span> sous-cutané)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges diagnostiques.</strong> <span class=\"kw-alerte\">Panaris abâtardi</span> par <span class=\"kw-clinique\">les</span> ATB : signes amoindris alors que le processus persiste (destructions osseuses, début de <span class=\"kw-clinique\">phlegmon</span>). <span class=\"kw-clinique\">Panaris herpétique</span> (vésicules J14, récidivant au même endroit) : <span class=\"kw-alerte\">chirurgie contre-indiquée</span> → <span class=\"kw-ttt\">valaciclovir</span>. <span class=\"kw-clinique\">Faux panaris d'Osler</span> (nodosités bleuâtres fugaces) → rechercher une <strong><span class=\"kw-clinique\">endocardite</span></strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 155 — Infection cutanéo-muqueuse · 152 — <span class=\"kw-clinique\">Endocardite</span> infectieuse</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/soft-tissue-abscess","label":"Radiopaedia : Soft tissue abscess"}]},{"id":"349-10","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évoquer le diagnostic de phlegmon des gaines","contenu":"<p>Le <span class=\"kw-clinique\">phlegmon</span> des gaines (ténosynovite des fléchisseurs) est une <span class=\"kw-alerte\">urgence chirurgicale</span> : son diagnostic est <strong>clinique ⭐⭐⭐⭐⭐</strong>. Spécificité = présence de liquide dans la <span class=\"kw-clinique\">gaine synoviale</span>.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-clinique\">Les</span> 4 signes de KANAVEL.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Œdème digital</span></li>\n          <li><span class=\"kw-clinique\">Douleur sur le trajet de la gaine</span></li>\n          <li><span class=\"kw-alerte\">Douleur à l'extension passive du doigt</span></li>\n          <li><span class=\"kw-alerte\">Attitude en crochet (flessum)</span> — inconstant (atteinte des tendons fléchisseurs)</li>\n        </ul>\n      </div>\n      <p><strong>Signe de Gosset</strong> (signe <span class=\"kw-clinique\">les</span> plus discriminant) : <span class=\"kw-alerte\">douleur maximale au cul-de-sac proximal de la gaine</span> (analogie à la défense de la <span class=\"kw-clinique\">péritonite</span>) :</p>\n      <ul>\n        <li>En regard des <span class=\"kw-clinique\">plis de flexion des MCP</span> pour <span class=\"kw-clinique\">les</span> 2ᵉ, 3ᵉ, 4ᵉ doigts</li>\n        <li>En regard du <span class=\"kw-clinique\">poignet</span> pour le pouce et le 5ᵉ doigt (gaines radiale et ulnaire)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Signe négatif initial capital.</strong> Le doigt est <strong>non <span class=\"kw-etio\">inflammatoire</span></strong> au début (« la peau du ventre n'est pas rouge dans une <span class=\"kw-clinique\">péritonite</span> ») : c'est ce qui distingue le <span class=\"kw-clinique\">phlegmon</span> des autres infections superficielles (périonyxis, cellulite, <span class=\"kw-clinique\">abcès</span>).</div>\n      <p><strong><span class=\"kw-clinique\">Les</span> 3 stades</strong> (<span class=\"kw-def\">classification</span> de Michon modifiée par Sokolov — <span class=\"kw-alerte\">discernables uniquement au bloc opératoire</span>, ici simple orientation) :</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-def\">Stade</span> 1<br><span class=\"kw-etio\">inflammatoire</span></th><th><span class=\"kw-chiffre\">Stade 2</span><br>purulente</th><th><span class=\"kw-chiffre\">Stade 3</span><br>nécrosante</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Liquide / synoviale</strong></td><td>clair ou louche ; hyperhémie</td><td>trouble/purulent ; synoviale congestive (2A) à lie-de-vin (2B)</td><td>—</td></tr>\n          <tr><td><strong>Tendon</strong></td><td>intact</td><td>intact</td><td><span class=\"kw-alerte\">nécrose ± étendue</span></td></tr>\n          <tr><td><strong>Inspection</strong></td><td>pas de crochet</td><td><span class=\"kw-alerte\">crochet irréductible</span></td><td><span class=\"kw-alerte\">disparition du crochet</span> (<span class=\"kw-alerte\">rupture</span> tendineuse), fistulisation</td></tr>\n          <tr><td><strong>Signes généraux</strong></td><td>absents</td><td><span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">tachycardie</span></td><td><span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">tachycardie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Latéralité & paraclinique.</strong> <span class=\"kw-alerte\">Phlegmon à bascule</span> : <span class=\"kw-clinique\">les</span> gaines du pouce et du 5ᵉ doigt communiquent au canal carpien (<span class=\"kw-chiffre\">50-80 %</span>) → contamination différée de l'autre doigt extrême. L'<span class=\"kw-imagerie\">échographie</span> peut détecter le liquide dans la gaine et un <span class=\"kw-clinique\">phlegmon</span> à bascule, mais le diagnostic reste <strong>clinique</strong>. <strong>DD</strong> : ténosynovite mécanique (pas de crochet, pas de <span class=\"kw-clinique\">porte d'entrée</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « PEC médico-chirurgicale d'un <span class=\"kw-clinique\">phlegmon</span> des gaines » · Item 156 — Infection ostéo-articulaire</em></p>","frequence":5},{"id":"349-11","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les critères cliniques de gravité et les indications de l'hospitalisation","contenu":"<p>La présence de facteurs de gravité <strong>accélère l'indication chirurgicale</strong> et conduit à l'<span class=\"kw-alerte\">hospitalisation</span>.</p>\n      <div class=\"callout callout-danger\"><strong>Facteurs de gravité d'une infection de la main.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Signes généraux</span> en rapport avec l'infection (<span class=\"kw-clinique\">fièvre</span>)</li>\n          <li>Signes locaux : collection en formation, aspect <span class=\"kw-etio\">inflammatoire</span>, <span class=\"kw-alerte\">exposition des structures sous-jacentes</span> (tendons, os, articulations)</li>\n          <li><span class=\"kw-alerte\">Cinétique rapide</span> (en quelques heures / jours)</li>\n          <li><span class=\"kw-def\">Terrain</span> pouvant décompenser (<span class=\"kw-etio\">diabète</span>, <span class=\"kw-ci\">insuffisance rénale</span>, hémopathie)</li>\n          <li><span class=\"kw-clinique\">Immunodépression</span> (<span class=\"kw-etio\">diabète</span>, toxicomanie, SIDA, splénectomie, <span class=\"kw-ttt\">immunosuppresseurs</span>)</li>\n          <li><span class=\"kw-ttt\">Anti-inflammatoires</span> (per os / topiques) : abâtardissent le tableau clinique</li>\n        </ul>\n      </div>\n      <p><strong>Indications chirurgicales selon le degré d'<span class=\"kw-alerte\">urgence</span></strong></p>\n      <table >\n        <thead><tr><th>Urgence absolue (dans <span class=\"kw-clinique\">les</span> heures)</th><th>Urgence relative (jours suivants)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Abcès</span></li>\n                <li><span class=\"kw-alerte\">Phlegmon des gaines</span></li>\n                <li><span class=\"kw-alerte\">Injection de liquides sous pression</span></li>\n                <li><span class=\"kw-alerte\">Fasciite nécrosante</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Périonyxis pulsatile</li>\n                <li><span class=\"kw-clinique\">Abcès</span> pulpaire</li>\n                <li>Morsure infectée (<span class=\"kw-chiffre\">> 24 h</span>)</li>\n                <li>Ostéite, arthrite</li>\n                <li>Exposition d'organe noble</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Critères d'<span class=\"kw-alerte\">hospitalisation</span></strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Évolution rapide</span> (aggravation en heures/jours)</li>\n        <li><span class=\"kw-clinique\">Terrain à risque</span> / <span class=\"kw-clinique\">immunosuppression</span></li>\n        <li>Tableau masqué par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span></li>\n        <li><span class=\"kw-alerte\">Morsure infectée</span>, injection sous pression</li>\n        <li><span class=\"kw-alerte\">Phlegmon des gaines</span>, ostéite/arthrite, exposition d'organe noble</li>\n        <li><span class=\"kw-alerte\">Fasciite nécrosante</span> (<span class=\"kw-alerte\">urgence</span> chirurgicale absolue)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Indication opératoire (synthèse).</strong> <span class=\"kw-def\">Stade</span> <span class=\"kw-alerte\">collecté</span>, stade <span class=\"kw-alerte\">compliqué</span>, ou <span class=\"kw-ttt\">échec à 48 h du traitement médical</span>. L'<span class=\"kw-alerte\">injection sous pression</span> de liquides industriels = <span class=\"kw-alerte\">urgence</span> chirurgicale absolue (agression physique + chimique).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> · 156 — Infection ostéo-articulaire</em></p>","frequence":0},{"id":"349-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge médico-chirurgicale d'un abcès et d'un panaris","contenu":"<p>Le traitement dépend du <strong><span class=\"kw-def\">stade</span></strong> : <span class=\"kw-clinique\">médical</span> au stade phlegmasique, <span class=\"kw-alerte\">chirurgical</span> au stade collecté. L'<span class=\"kw-clinique\">évolution</span> est favorable sous traitement bien conduit dans la majorité des cas.</p>\n      <h4 class=\"kw-def\">1 · Traitement médical (<span class=\"kw-def\">stade</span> phlegmasique)</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Bains pluriquotidiens au sérum physiologique</span> ; antiseptique (<span class=\"kw-ttt\">chlorhexidine</span> ou <span class=\"kw-ttt\">povidone iodée</span>) <strong>uniquement si plaie souillée</strong> ; <span class=\"kw-ci\">Dakin proscrit en usage routinier</span> ❌ (cytotoxique pour les fibroblastes, retarde la cicatrisation) + pansements</li>\n        <li><span class=\"kw-ttt\">ATB per os non systématique</span>,<span class=\"kw-chiffre\"> 48 h</span>, probabiliste anti-<span class=\"kw-etio\">staphylocoque</span> (cloxacilline, <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span>, pristinamycine si <span class=\"kw-ci\">allergie</span>)</li>\n        <li><span class=\"kw-clinique\">Panaris</span> sous-cutané : immobilisation en <span class=\"kw-clinique\">position intrinsèque plus</span> (flexion MCP, extension <span class=\"kw-ttt\">IPP</span>)</li>\n        <li><span class=\"kw-ci\">AINS à proscrire</span> ❌ ; <span class=\"kw-def\">surveillance</span> rapprochée</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Atteintes à traitement médical spécifique.</strong> Pasteurellose (<span class=\"kw-ttt\">amoxicilline</span>, <span class=\"kw-ttt\">doxycycline</span> si <span class=\"kw-ci\">allergie</span>) ; <span class=\"kw-clinique\">panaris</span> herpétique (<span class=\"kw-ttt\">aciclovir</span>) ; <span class=\"kw-clinique\">nodule</span> d'Orf (parapoxvirus du trayeur) — pour ces deux derniers, la <span class=\"kw-alerte\">chirurgie peut aggraver</span> <span class=\"kw-clinique\">les</span> lésions.</div>\n      <h4 class=\"kw-def\">2 · Traitement chirurgical (<span class=\"kw-def\">stade</span> collecté / compliqué / échec à<span class=\"kw-chiffre\"> 48 h</span>)</h4>\n      <ul>\n        <li>Prévenir le patient (séquelles esthétiques, cicatrisation longue)</li>\n        <li><span class=\"kw-alerte\">Radiographie standard systématique</span> avant exploration pour toute <span class=\"kw-clinique\">plaie profonde</span>, <span class=\"kw-clinique\">morsure</span> ou <span class=\"kw-clinique\">plaie articulaire</span> : recherche d'un <span class=\"kw-alerte\">corps étranger radio-opaque</span> et d'une <span class=\"kw-alerte\">atteinte osseuse</span> (fracture, ostéite débutante).</li>\n        <li>1ᵉʳ temps <span class=\"kw-clinique\">exploratoire</span> : <span class=\"kw-clinique\">nécrose</span> ? organe touché ? corps étranger ?</li>\n        <li><span class=\"kw-ttt\">Excision des tissus infectés / nécrosés</span> + ablation d'un corps étranger</li>\n        <li>Prélèvements bactériologiques peropératoires</li>\n        <li><span class=\"kw-ttt\">Lavage abondant au sérum salé isotonique</span></li>\n        <li><span class=\"kw-clinique\">Cicatrisation dirigée</span> (plaie laissée ouverte) + immobilisation fonctionnelle</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Spécificités selon la forme.</strong> <span class=\"kw-def\">Abcès</span> : mise à plat-<span class=\"kw-ttt\">drainage</span>, ATB probabiliste <strong>après</strong> la <span class=\"kw-ttt\">chirurgie</span> (sans drainage, l'ATB ne diffuse pas dans l'<span class=\"kw-clinique\">abcès</span>). <span class=\"kw-alerte\">Panaris pulpaire</span> : incisions pulpaires <span class=\"kw-ttt\">en Zig-Zag de Bruner</span> ; <span class=\"kw-ci\">éviter l'ouverture « en gueule de requin »</span> ❌ (compromet la vascularisation pulpaire). <strong>Enfant</strong> : la <span class=\"kw-alerte\">matrice unguéale peut être détruite en 48 h</span> → <span class=\"kw-alerte\">urgence</span>.</div>\n      <p><strong>Mesures associées</strong> : traitement de la <span class=\"kw-clinique\">porte d'entrée</span> ; <span class=\"kw-ttt\">SAT-VAT</span> ; arrêt de travail (métiers exposés) ; éducation (hygiène, onychophagie) ; <span class=\"kw-ttt\">antalgiques</span> ; rééducation-kinésithérapie.</p>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « PEC médico-chirurgicale d'un <span class=\"kw-clinique\">phlegmon</span> des gaines » · Item 146 — <span class=\"kw-ttt\">Vaccination</span> (SAT-VAT)</em></p>","frequence":0},{"id":"349-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge médico-chirurgicale d'un phlegmon des gaines","contenu":"<p>Le <span class=\"kw-clinique\">phlegmon</span> des gaines est une <span class=\"kw-alerte\">urgence chirurgicale systématique</span> ⭐⭐⭐⭐⭐ : le traitement chirurgical est indiqué <strong>à tous <span class=\"kw-clinique\">les</span> stades</strong>, le geste étant choisi en peropératoire selon l'aspect du liquide, de la synoviale et du tendon.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Geste chirurgical de choix</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Stade 1</strong></span> — ténosynovite <span class=\"kw-etio\">inflammatoire</span></td><td><span class=\"kw-ttt\">Lavage de la gaine par ses extrémités</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Stade 2</strong></span> — ténosynovite purulente (crochet)</td><td><span class=\"kw-ttt\">Lavage + synovectomie complète</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Stade 3</strong></span> — ténosynovite nécrosante (<span class=\"kw-alerte\">rupture</span> du tendon)</td><td><span class=\"kw-alerte\">Chirurgie de sauvetage : excision de tous les tissus nécrotiques</span> ; <strong>séquelles constantes</strong> (fléchisseur excisé)</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Prise en charge post-opératoire</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Attelle</span> maintenant <span class=\"kw-clinique\">les</span> doigts en <strong>position intrinsèque plus</strong> (flexion MCP, extension des interphalangiennes)</li>\n        <li><span class=\"kw-ttt\">Antibiothérapie probabiliste</span> après prélèvements :\n          <ul>\n            <li>Cas général : <span class=\"kw-ttt\">amoxicilline-acide clavulanique 7 jours</span></li>\n            <li>Morsure : <span class=\"kw-ttt\">cyclines 10 jours</span> (pasteurellose)</li>\n          </ul>\n        </li>\n        <li>Puis <span class=\"kw-ttt\">adaptée aux germes</span> documentés (durée/type selon germe, tissus, <span class=\"kw-def\">terrain</span> ; <span class=\"kw-clinique\">phlegmon</span> à mycobactéries traité plusieurs mois)</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Pronostic</span>.</strong> <span class=\"kw-clinique\">Évolution</span> <span class=\"kw-clinique\">favorable</span> sous traitement bien conduit dans la majorité des cas, mais <span class=\"kw-alerte\">séquelles fonctionnelles si traitement tardif</span> (<span class=\"kw-def\">stade</span> 2 ou 3) ⭐ → d'où l'<span class=\"kw-alerte\">urgence</span> du diagnostic et de la <span class=\"kw-ttt\">chirurgie</span>.</div>\n      <p><strong>Mesures associées</strong> : traitement de la <span class=\"kw-clinique\">porte d'entrée</span> ; <span class=\"kw-ttt\">SAT-VAT</span> ; <span class=\"kw-ttt\">prévention rabique</span> si morsure ; arrêt de travail ; éducation ; rééducation-kinésithérapie (lutte contre l'enraidissement).</p>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « savoir évoquer le diagnostic de <span class=\"kw-clinique\">phlegmon</span> des gaines » · Item 156 — Infection ostéo-articulaire</em></p>","frequence":5}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> absolue (dans <span class=\"kw-clinique\">les</span> heures) :</strong> <span class=\"kw-alerte\">abcès</span>, <span class=\"kw-alerte\">phlegmon des gaines</span>, <span class=\"kw-alerte\">injection de liquide sous pression</span>, <span class=\"kw-alerte\">fasciite nécrosante</span> — risque de séquelles fonctionnelles ou de <span class=\"kw-alerte\">pronostic vital</span>.<br><strong>Urgence relative (jours suivants) :</strong> <span class=\"kw-clinique\">périonyxis pulsatile</span>, <span class=\"kw-clinique\">abcès pulpaire</span>, <span class=\"kw-etio\">morsure infectée</span> (<span class=\"kw-chiffre\">> 24 h</span>), <span class=\"kw-alerte\">ostéite / arthrite</span>, exposition d'organe noble.<br><strong>Indication chirurgicale :</strong> <span class=\"kw-def\">stade</span> <span class=\"kw-clinique\">collecté</span>, stade <span class=\"kw-clinique\">compliqué</span> ou <span class=\"kw-alerte\">échec à 48 h</span> du traitement médical.<br><strong>Enfant :</strong> la <span class=\"kw-clinique\">matrice unguéale</span> peut être détruite en <span class=\"kw-chiffre\">48 h</span> → prise en charge urgente.</p>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> si :</strong> <span class=\"kw-clinique\">évolution rapide</span> (heures/jours), <span class=\"kw-alerte\">terrain à risque</span> (<span class=\"kw-etio\">diabète</span>, <span class=\"kw-ci\">insuffisance rénale</span>, hémopathie), <span class=\"kw-alerte\">immunodépression</span> (diabète, toxicomanie IV, <span class=\"kw-etio\">VIH</span>, splénectomie, <span class=\"kw-ttt\">immunosuppresseurs</span>), <span class=\"kw-alerte\">masquage clinique par AINS</span>.<br><strong>Toujours hospitaliser :</strong> <span class=\"kw-alerte\">phlegmon des gaines</span>, <span class=\"kw-alerte\">fasciite nécrosante</span>, <span class=\"kw-alerte\">injection de liquide sous pression</span>, <span class=\"kw-alerte\">ostéite / arthrite</span>, <span class=\"kw-etio\">morsure infectée</span>, exposition d'organe noble.<br><strong>Orientation :</strong> avis <span class=\"kw-ttt\">chirurgien de la main</span> ; <span class=\"kw-ttt\">centre antirabique (CAR)</span> si morsure à risque rabique.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Signes généraux infectieux</span> : <span class=\"kw-clinique\">fièvre</span>, frissons (<span class=\"kw-etio\">bactériémie</span>)</li><li><span class=\"kw-clinique\">Douleur pulsatile, lancinante, insomniante</span> = <span class=\"kw-def\">stade</span> <span class=\"kw-alerte\">collecté irréversible</span></li><li><strong>4 signes de Kanavel</strong> (<span class=\"kw-clinique\">phlegmon</span> des gaines) : <span class=\"kw-clinique\">œdème digital</span>, <span class=\"kw-clinique\">douleur sur le trajet de la gaine</span>, <span class=\"kw-clinique\">douleur à l'extension passive</span>, <span class=\"kw-clinique\">crochet / flessum</span> irréductible</li><li><strong>Signe de Gosset</strong> : <span class=\"kw-clinique\">douleur au cul-de-sac proximal de la gaine</span> (analogie à la défense d'une <span class=\"kw-clinique\">péritonite</span>)</li><li><span class=\"kw-alerte\">Cinétique d'évolution rapide</span> (en quelques heures ou jours)</li><li><span class=\"kw-alerte\">Exposition / atteinte de structures nobles</span> : tendon, os, articulation</li><li><span class=\"kw-etio\">Fasciite nécrosante</span> (dermo-hypodermite nécrosante)</li><li><span class=\"kw-alerte\">Immunodéprimé / asplénique mordu</span> → <span class=\"kw-etio\">Capnocytophaga canimorsus</span> → <span class=\"kw-alerte\">purpura fulminans</span> (<span class=\"kw-def\">mortalité</span> quasi-constante)</li><li><span class=\"kw-ci\">AINS / corticoïdes</span> : abâtardissent le tableau et masquent <span class=\"kw-clinique\">les</span> signes (<span class=\"kw-clinique\">panaris</span> « abâtardi »)</li><li><span class=\"kw-clinique\">Plaie dorsale de MCP</span> par coup de poing = <span class=\"kw-alerte\">arthrite</span> jusqu'à preuve du contraire</li></ul>","principes":"<p><strong>Principe :</strong> le <span class=\"kw-ttt\">geste chirurgical</span> réalise l'<span class=\"kw-ttt\">exérèse</span> de la charge <span class=\"kw-etio\">bactérienne</span> (collection, tissus nécrotiques) ; le <span class=\"kw-ttt\">traitement médical</span> suffit si le diagnostic est <span class=\"kw-clinique\">précoce</span>.</p><p><strong>Traitement médical (<span class=\"kw-def\">stade</span> phlegmasique)</strong></p><p>Médical</p><ul><li><span class=\"kw-ttt\">Bains pluriquotidiens d'antiseptiques incolores</span> (Dakin, hexomédine diluée)</li><li><span class=\"kw-ttt\">Antibiothérapie PO</span> non systématique, <span class=\"kw-chiffre\">48 h</span>, probabiliste anti-staph (cloxacilline, oxacilline, <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span>, pristinamycine si <span class=\"kw-ci\">allergie</span>)</li><li><span class=\"kw-clinique\">Panaris</span> sous-cutané : immobilisation en <span class=\"kw-clinique\">position intrinsèque plus</span> (flexion MCP, extension <span class=\"kw-ttt\">IPP</span>)</li><li><span class=\"kw-ci\">AINS proscrits</span></li></ul><p><strong>Traitement chirurgical (<span class=\"kw-def\">stade</span> collecté / compliqué)</strong></p><p><span class=\"kw-ttt\">Chirurgie</span></p><ul><li>Indications : <span class=\"kw-def\">stade</span> <span class=\"kw-clinique\">collecté</span>, <span class=\"kw-clinique\">compliqué</span> ou <span class=\"kw-alerte\">échec à 48 h</span> du traitement médical</li><li>1er temps exploratoire + <span class=\"kw-ttt\">excision des tissus infectés / nécrosés</span> + ablation d'un corps étranger</li><li><span class=\"kw-ttt\">Prélèvements bactériologiques peropératoires</span> puis lavage abondant au sérum salé isotonique</li><li><span class=\"kw-ttt\">Cicatrisation dirigée</span> + immobilisation en position intrinsèque plus</li><li><span class=\"kw-clinique\">Panaris</span> pulpaire : <span class=\"kw-ttt\">incisions Zig Zag de Bruner</span> (éviter la gueule de requin)</li></ul><p><strong><span class=\"kw-clinique\">Phlegmon</span> des gaines</strong></p><p><span class=\"kw-clinique\">Phlegmon</span></p><ul><li><span class=\"kw-alerte\">Urgence chirurgicale systématique à tous les stades</span> (Michon-Sokolov 1/2/3)</li><li><span class=\"kw-ttt\">Lavage de la gaine</span> (<span class=\"kw-def\">stade</span> 1), <span class=\"kw-ttt\">synovectomie</span> (<span class=\"kw-chiffre\">stade 2</span>), excision des tissus nécrotiques (stade 3)</li><li><span class=\"kw-ttt\">Augmentin 7 jours</span> (cas général) ; <span class=\"kw-ttt\">cyclines 10 jours</span> si morsure (pasteurellose)</li><li><span class=\"kw-alerte\">Séquelles fonctionnelles</span> si traitement tardif (<span class=\"kw-chiffre\">stade 2 ou 3</span>)</li></ul><p><strong>Morsure</strong></p><p>Morsure</p><ul><li><span class=\"kw-alerte\">Urgence médico-chirurgicale</span> : toujours plaie profonde infectée</li><li><span class=\"kw-ttt\">Chirurgie</span> : AG, exploration, <span class=\"kw-ttt\">lavage abondant +++</span>, parage, <span class=\"kw-ttt\">drainage</span>, suture lâche</li><li><span class=\"kw-ttt\">Augmentin 5 jours</span> ; <span class=\"kw-ttt\">doxycycline</span> si <span class=\"kw-ci\">allergie</span> / adulte (<span class=\"kw-etio\">Pasteurella multocida</span>)</li><li><span class=\"kw-ttt\">Prévention antirabique</span> (CAR) + <span class=\"kw-ttt\">SAT ± VAT</span></li><li><span class=\"kw-ci\">Pas de suture</span> si parage insatisfaisant ; <span class=\"kw-ci\">pas de pansement occlusif</span></li></ul><p><strong>Formes à traitement médical</strong></p><p>Formes particulières</p><ul><li><span class=\"kw-etio\">Pasteurellose</span> : <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">1ère intention</span>, <span class=\"kw-ttt\">doxycycline</span> si <span class=\"kw-ci\">allergie</span></li><li><span class=\"kw-etio\">Panaris herpétique</span> : <span class=\"kw-ttt\">valaciclovir / aciclovir</span> ; <span class=\"kw-ci\">chirurgie contre-indiquée</span> (risque d'extension)</li><li><span class=\"kw-etio\">Nodule d'Orf</span>, piqûre d'oursin : la <span class=\"kw-ci\">chirurgie peut aggraver</span> <span class=\"kw-clinique\">les</span> lésions</li></ul><p><strong>Mesures associées</strong></p><p>Associé</p><ul><li><span class=\"kw-ttt\">Traitement de la porte d'entrée</span></li><li><span class=\"kw-ttt\">SAT-VAT</span> si non / mal vacciné</li><li>Arrêt de travail (métiers de la restauration)</li><li><span class=\"kw-clinique\">Éducation</span> : hygiène, correction manucure / onychophagie</li><li><span class=\"kw-ttt\">Rééducation-kinésithérapie</span> (anti-enraidissement) + <span class=\"kw-ttt\">antalgiques</span></li></ul>","suivi":"<p><strong><span class=\"kw-def\">Réévaluation</span> systématique à <span class=\"kw-chiffre\">48 h</span></strong> du traitement médical : passage à la <span class=\"kw-ttt\">chirurgie</span> en cas d'<span class=\"kw-alerte\">échec</span> ou de collection.<br><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> probabiliste anti-<span class=\"kw-etio\">staphylocoque</span>, puis <span class=\"kw-ttt\">adaptée aux prélèvements peropératoires</span>.<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-clinique\">évolution favorable</span> sous traitement bien conduit dans la majorité des cas ; <span class=\"kw-alerte\">séquelles fonctionnelles</span> si traitement tardif (<span class=\"kw-clinique\">phlegmon</span> <span class=\"kw-chiffre\">stade 2 ou 3</span>).<br><strong>Morsure :</strong> <span class=\"kw-ttt\">surveillance vétérinaire</span> du chien mordeur à <span class=\"kw-chiffre\">J0, J7, J15</span> (décide la <span class=\"kw-ttt\">vaccination</span> antirabique du mordu).<br><strong>Enfant :</strong> <span class=\"kw-def\">surveillance</span> rapprochée (<span class=\"kw-clinique\">matrice unguéale</span> fragile).</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-155.pdf","label":"PILLY étudiant 2023 — Item 155 (infections cutanéo-muqueuses & des phanères)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Infection aiguë des parties molles de la main — Démarche : éliminer une urgence absolue, puis stadifier l'infection","detail":"<h4>Infection aiguë des parties molles de la main — CAT — Du triage de gravité à la décision médico-chirurgicale</h4>","branches":[{"to":"t_urgabs","label":"Sepsis / nécrose / injection sous pression","color":"red"},{"to":"q_morsure","label":"Morsure","color":"amber"},{"to":"q_doigt","label":"Panaris / abcès du doigt","color":"blue"}]},{"id":"t_urgabs","kind":"terminal","label":"Urgence absolue — bloc dans les heures","color":"red","detail":"<h4>Tableaux</h4><ul><li><span class=\"kw-alerte\">Fasciite nécrosante</span> (dermo-hypodermite nécrosante)</li><li><span class=\"kw-alerte\">Injection de liquide sous pression</span> (peinture, solvant, huile)</li><li><span class=\"kw-clinique\">Sepsis</span> / <span class=\"kw-etio\">bactériémie</span> (<span class=\"kw-clinique\">fièvre</span>, frissons)</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Excision chirurgicale large en urgence</span> + prélèvements</li><li><span class=\"kw-ttt\">Antibiothérapie IV</span> probabiliste ; <span class=\"kw-alerte\">réanimation</span> si <span class=\"kw-alerte\">sepsis</span></li></ul>"},{"id":"q_morsure","kind":"decision","label":"Morsure (animale ou humaine) ? — Toute morsure = plaie profonde infectée = urgence médico-chirurgicale","branches":[{"to":"t_capno","label":"Immunodéprimé / asplénique","color":"red"},{"to":"t_morsure","label":"Immunocompétent","color":"amber"}]},{"id":"t_capno","kind":"terminal","label":"Morsure chez l'immunodéprimé / asplénique","color":"red","detail":"<h4><span class=\"kw-alerte\">Red flag</span></h4><ul><li><span class=\"kw-etio\">Capnocytophaga canimorsus</span> → <span class=\"kw-alerte\">purpura fulminans</span></li><li><span class=\"kw-def\">Mortalité</span> <span class=\"kw-alerte\">quasi-constante</span> chez l'immunodéprimé</li></ul><h4>CAT</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> + <span class=\"kw-ttt\">antibiothérapie IV</span> urgente</li><li>Parage chirurgical + prévention antirabique / tétanique</li></ul>"},{"id":"t_morsure","kind":"terminal","label":"Morsure chez l'immunocompétent — urgence médico-chir","color":"amber","detail":"<h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li>AG, <span class=\"kw-ttt\">exploration</span> du trajet des crocs</li><li><span class=\"kw-ttt\">Lavage abondant +++</span>, parage, <span class=\"kw-ttt\">drainage</span>, suture lâche</li></ul><h4>Médical</h4><ul><li><span class=\"kw-ttt\">Augmentin 5 jours</span> (<span class=\"kw-ttt\">doxycycline</span> si <span class=\"kw-ci\">allergie</span> / adulte, <span class=\"kw-etio\">Pasteurella</span>)</li><li><span class=\"kw-ttt\">Prévention antirabique</span> (CAR) + <span class=\"kw-ttt\">SAT ± VAT</span></li></ul>"},{"id":"q_doigt","kind":"decision","label":"Panaris / abcès du doigt (sans morsure) — Rechercher d'abord les signes de phlegmon des gaines","branches":[{"to":"t_phlegmon","label":"Signes de Kanavel / Gosset +","color":"red"},{"to":"q_stade","label":"Périonyxis / panaris / abcès","color":"blue"}]},{"id":"t_phlegmon","kind":"terminal","label":"Phlegmon des gaines — urgence chirurgicale systématique","color":"red","detail":"<h4>Diagnostic</h4><ul><li><strong>4 signes de Kanavel</strong> : <span class=\"kw-clinique\">œdème</span>, douleur sur la gaine, <span class=\"kw-clinique\">douleur à l'extension passive</span>, <span class=\"kw-clinique\">crochet</span></li><li><strong>Signe de Gosset</strong> : <span class=\"kw-clinique\">douleur au cul-de-sac proximal</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Chirurgie à tous les stades</span> (Michon-Sokolov 1/2/3)</li><li><span class=\"kw-ttt\">Augmentin 7 j</span> (<span class=\"kw-ttt\">cyclines 10 j</span> si morsure)</li></ul>"},{"id":"q_stade","kind":"decision","label":"Quel stade évolutif ? — Stade collecté = douleur pulsatile insomniante (irréversible)","branches":[{"to":"t_collecte","label":"Collecté (pulsatile, insomniant)","color":"amber"},{"to":"t_medical","label":"Phlegmasique (non collecté)","color":"green"}]},{"id":"t_collecte","kind":"terminal","label":"Collection simple — mise à plat chirurgicale (urgence relative)","color":"amber","detail":"<h4>Tableaux</h4><ul><li><span class=\"kw-clinique\">Périonyxis pulsatile</span>, <span class=\"kw-clinique\">abcès pulpaire</span>, <span class=\"kw-clinique\">panaris</span> collecté</li><li>Douleur <span class=\"kw-clinique\">pulsatile, insomniante</span> ; collection rénitente sous tension</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Mise à plat chirurgicale</span> + excision + prélèvements</li><li><span class=\"kw-clinique\">Panaris</span> pulpaire : <span class=\"kw-ttt\">incisions Zig Zag de Bruner</span> (éviter la gueule de requin)</li><li><span class=\"kw-ttt\">Antibiothérapie</span> seulement si <span class=\"kw-def\">terrain</span> fragile ou diffusion</li></ul>"},{"id":"t_medical","kind":"terminal","label":"Stade phlegmasique — traitement médical ambulatoire","color":"green","detail":"<h4>Critères</h4><ul><li>Douleur modérée + signes inflammatoires, <span class=\"kw-clinique\">pas de collection</span> ni pulsatilité, apyrexie</li><li><span class=\"kw-def\">Stade</span> encore <span class=\"kw-clinique\">réversible</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Bains d'antiseptiques incolores</span> (Dakin, hexomédine diluée)</li><li><span class=\"kw-ttt\">ATB PO</span> non systématique <span class=\"kw-chiffre\">48 h</span> (anti-staph) ; <span class=\"kw-ci\">AINS proscrits</span></li><li><span class=\"kw-alerte\">Réévaluation à 48 h</span> → <span class=\"kw-ttt\">chirurgie</span> si échec / collection</li></ul>"}]},"cards":[{"i":"55ef3a70b3db","n":349,"o":"349-1","u":"Définition","t":"Connaître les principales infections des parties molles","q":"Quelles sont les principales entités cliniques des infections aiguës des parties molles liées à la région péri-unguéale et à la pulpe ?","a":"<ul><li><strong>Région péri-unguéale</strong> : Périonyxis (paronychie)</li><li><strong>Pulpe et ses cloisons conjonctives</strong> : Panaris pulpaire</li></ul>"},{"i":"93979633b7ba","n":349,"o":"349-1","u":"Définition","t":"Connaître les principales infections des parties molles","q":"Comment les infections aiguës des parties molles, particulièrement celles de la main, sont-elles classées ?","a":"<p>Elles sont classées selon la <strong>structure anatomique atteinte</strong>.</p>"},{"i":"97668826d28b","n":349,"o":"349-1","u":"Définition","t":"Connaître les principales infections des parties molles","q":"Quelles entités cliniques des infections aiguës des parties molles sont associées au tissu cellulaire sous-cutané et à la gaine synoviale des fléchisseurs ?","a":"<ul><li><strong>Tissu cellulaire sous-cutané</strong> : Cellulite (panaris sous-cutané)</li><li><strong>Gaine synoviale des fléchisseurs</strong> : Phlegmon des gaines</li></ul>"},{"i":"dbe4103203d0","n":349,"o":"349-1","u":"Définition","t":"Connaître les principales infections des parties molles","q":"Quel est le principal piège anatomique concernant les infections de la main et ses conséquences thérapeutiques ?","a":"<p>Du fait des <strong>cloisonnements anatomiques</strong> de la main, une infection peut très vite se cloisonner et <strong>mimer un abcès</strong>, ce qui peut pousser à une <strong>intervention chirurgicale</strong>.</p>"},{"i":"e578765be832","n":349,"o":"349-1","u":"Définition","t":"Connaître les principales infections des parties molles","q":"Quels sont les trois grands cadres cliniques qui regroupent les infections aiguës des parties molles de la main ?","a":"<ul><li><strong>Panaris</strong> : périonyxis (paronychie aiguë), panaris sous-cutané (cellulite).</li><li><strong>Abcès</strong> : abcès sous-cutané, abcès de la main (espaces profonds), panaris pulpaire.</li><li><strong>Phlegmon</strong> : phlegmon des gaines (ténosynovite).</li></ul>"},{"i":"19d7e82ed3a2","n":349,"o":"349-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic de phlegmon des gaines","q":"Qu'est-ce qu'un phlegmon à bascule, et quels doigts sont principalement concernés ?","a":"<p>Un phlegmon à bascule survient lorsque les gaines du <strong>pouce et du 5<sup>e</sup> doigt</strong> communiquent au niveau du canal carpien (présent chez <strong>50 à 80 %</strong> des individus). Cela peut entraîner une contamination différée de l'un à l'autre de ces doigts.</p>"},{"i":"1d6686ffb919","n":349,"o":"349-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic de phlegmon des gaines","q":"Quels sont les quatre signes cliniques de Kanavel qui permettent d'évoquer un phlegmon des gaines ?","a":"<ul><li><strong>Œdème digital</strong> (gonflement du doigt).</li><li><strong>Douleur sur le trajet de la gaine</strong> synoviale.</li><li><strong>Douleur à l'extension passive</strong> du doigt.</li><li><strong>Attitude en crochet</strong> (flessum), inconstante, due à l'atteinte des tendons fléchisseurs.</li></ul>"},{"i":"2f70e35c2614","n":349,"o":"349-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic de phlegmon des gaines","q":"Comment sont classifiés les stades d'un phlegmon des gaines selon Michon modifiée par Sokolov, et quelle est leur utilité au diagnostic clinique ?","a":"<p>Les trois stades sont :</p><ul><li>Stade 1 : <strong>inflammatoire</strong>.</li><li>Stade 2 : <strong>purulent</strong>.</li><li>Stade 3 : <strong>nécrosant</strong>.</li></ul><p>Ces stades ne sont discernables qu'au bloc opératoire et servent principalement d'orientation thérapeutique, le diagnostic initial restant clinique.</p>"},{"i":"a3968830fe66","n":349,"o":"349-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic de phlegmon des gaines","q":"Quelle est l'urgence associée au diagnostic de phlegmon des gaines ?","a":"<p>Le phlegmon des gaines est une <strong>urgence chirurgicale</strong>.</p>"},{"i":"e1458323d0bf","n":349,"o":"349-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic de phlegmon des gaines","q":"Comment se manifeste le signe de Gosset, considéré comme le plus discriminant dans le diagnostic de phlegmon des gaines ?","a":"<p>Le signe de Gosset se manifeste par une <strong>douleur maximale au cul-de-sac proximal de la gaine</strong>, c'est-à-dire :</p><ul><li>En regard des <strong>plis de flexion des MCP</strong> (articulations métacarpo-phalangiennes) pour les 2<sup>e</sup>, 3<sup>e</sup> et 4<sup>e</sup> doigts.</li><li>En regard du <strong>poignet</strong> pour le pouce et le 5<sup>e</sup> doigt (gaines radiale et ulnaire).</li></ul>"},{"i":"e70e55bdb1b2","n":349,"o":"349-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic de phlegmon des gaines","q":"Quel est le signe clinique distinctif, souvent négatif initialement, qui permet de différencier le phlegmon des gaines des autres infections superficielles du doigt ?","a":"<p>Le doigt est <strong>non inflammatoire au début</strong>, contrairement aux autres infections superficielles comme le périonyxis, la cellulite ou l'abcès. La peau n'est pas rouge dans les premiers temps.</p>"},{"i":"c00307a48366","n":349,"o":"349-11","u":"Identifier une urgence","t":"Connaître les critères cliniques de gravité et les indications de l'hospitalisation","q":"Quels sont les signes locaux de gravité d'une infection aiguë des parties molles, en particulier au niveau de la main ?","a":"<p>Les signes locaux de gravité incluent :</p><ul><li>Une <strong>collection en formation</strong> (abcès).</li><li>Un aspect <strong>inflammatoire</strong> marqué.</li><li>L'<strong>exposition des structures sous-jacentes</strong> (tendons, os, articulations).</li><li>Une <strong>cinétique rapide</strong> d'évolution (aggravation en quelques heures à jours).</li></ul>"},{"i":"f3d61ca5b4c5","n":349,"o":"349-11","u":"Identifier une urgence","t":"Connaître les critères cliniques de gravité et les indications de l'hospitalisation","q":"Quelles sont les indications d'hospitalisation devant une infection aiguë des parties molles ?","a":"<p>Les indications d'hospitalisation comportent :</p><ul><li>Une <strong>évolution rapide</strong> (aggravation en quelques heures/jours).</li><li>Un <strong>terrain à risque</strong> ou une <strong>immunodépression</strong>.</li><li>Un <strong>tableau clinique masqué</strong> par la prise d'AINS.</li><li>Des situations spécifiques comme une <strong>morsure infectée</strong>, une <strong>injection sous pression</strong>.</li><li>Des atteintes graves : <strong>phlegmon des gaines</strong>, <strong>ostéite/arthrite</strong>, exposition d'un <strong>organe noble</strong>.</li><li>Une <strong>fasciite nécrosante</strong> (qui est une urgence chirurgicale absolue).</li><li>Toute <strong>indication opératoire</strong>, notamment un stade collecté, un stade compliqué ou un échec après 48h de traitement médical.</li><li>L'<strong>injection sous pression de liquides industriels</strong> (urgence chirurgicale absolue).</li></ul>"},{"i":"fad708deaf22","n":349,"o":"349-11","u":"Identifier une urgence","t":"Connaître les critères cliniques de gravité et les indications de l'hospitalisation","q":"Quels sont les signes généraux de gravité d'une infection aiguë des parties molles, en particulier au niveau de la main ?","a":"<p>Le principal signe général de gravité est la <strong>fièvre</strong>, témoignant d'une réponse systémique à l'infection.</p>"},{"i":"fb2af69a3a70","n":349,"o":"349-11","u":"Identifier une urgence","t":"Connaître les critères cliniques de gravité et les indications de l'hospitalisation","q":"Quels sont les facteurs liés au terrain du patient pouvant aggraver une infection aiguë des parties molles ?","a":"<p>Les facteurs de terrain pouvant aggraver l'infection et justifier une prise en charge rapide sont :</p><ul><li>Un terrain pouvant décompenser : <strong>diabète</strong>, <strong>insuffisance rénale</strong>, <strong>hémopathie</strong>.</li><li>Une situation d'<strong>immunodépression</strong> : diabète, toxicomanie, SIDA, splénectomie, traitements immunosuppresseurs.</li><li>La prise d'<strong>anti-inflammatoires</strong> (per os ou topiques) qui peuvent masquer le tableau clinique (abâtardissement).</li></ul>"},{"i":"4119d48d9255","n":349,"o":"349-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge médico-chirurgicale d'un abcès et d'un panaris","q":"Comment traiter un abcès ou un panaris au stade phlegmasique ?","a":"<p>Le traitement médical d'un abcès ou d'un panaris au stade phlegmasique repose sur :</p><ul><li>Des <strong>bains pluriquotidiens d'antiseptiques incolores</strong> (Dakin, hexomédine diluée) et pansements.</li><li>Une <strong>antibiothérapie per os non systématique</strong>, probabiliste anti-staphylocoque (cloxacilline, amoxicilline-acide clavulanique, pristinamycine si allergie), pendant 48 heures.</li><li>L'<strong>immobilisation en position intrinsèque plus</strong> (flexion MCP, extension IPP) pour le panaris sous-cutané.</li><li>La <strong>surveillance rapprochée</strong>.</li><li>L'<strong>interdiction des AINS</strong>.</li></ul>"},{"i":"667fb1cd0312","n":349,"o":"349-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge médico-chirurgicale d'un abcès et d'un panaris","q":"Quelles sont les mesures associées à la prise en charge d'un abcès ou d'un panaris ?","a":"<p>Les mesures associées sont :</p><ul><li>Traitement de la <strong>porte d'entrée</strong>.</li><li>Vérification de la vaccination <strong>SAT-VAT</strong> (séro-anatoxinothérapie tétanique).</li><li>Arrêt de travail (pour les métiers exposés).</li><li>Éducation du patient (hygiène, onychophagie).</li><li>Prescription d'<strong>antalgiques</strong>.</li><li><strong>Rééducation-kinésithérapie</strong> si nécessaire.</li></ul>"},{"i":"c9de35577889","n":349,"o":"349-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge médico-chirurgicale d'un abcès et d'un panaris","q":"Quand faut-il envisager un traitement chirurgical pour un abcès ou un panaris et quels sont les principes généraux ?","a":"<p>Le traitement chirurgical est indiqué au <strong>stade collecté</strong>, compliqué ou en cas d'échec du traitement médical à 48 heures. Les principes généraux incluent :</p><ul><li>Un <strong>1<sup>er</sup> temps exploratoire</strong> (recherche de nécrose, d'atteinte d'un organe ou d'un corps étranger).</li><li>L'<strong>excision des tissus infectés/nécrosés</strong> et l'ablation d'un corps étranger.</li><li>Des <strong>prélèvements bactériologiques peropératoires</strong>.</li><li>Un <strong>lavage abondant</strong> au sérum salé isotonique.</li><li>La <strong>cicatrisation dirigée</strong> (plaie laissée ouverte) et l'immobilisation fonctionnelle.</li><li>Une <strong>antibiothérapie probabiliste après la chirurgie</strong> (pour le panaris).</li></ul>"},{"i":"d07608273ad7","n":349,"o":"349-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge médico-chirurgicale d'un abcès et d'un panaris","q":"Quels sont les traitements spécifiques de certaines atteintes médicales des parties molles ?","a":"<p>Certaines infections des parties molles ont un traitement médical spécifique :</p><ul><li><strong>Pasteurellose</strong> : amoxicilline (doxycycline si allergie).</li><li><strong>Panaris herpétique</strong> : aciclovir.</li><li><strong>Nodule d'Orf</strong> (parapoxvirus du trayeur) : pas de traitement spécifique, la chirurgie peut aggraver les lésions pour ces deux dernières.</li></ul>"},{"i":"f510d544bfb4","n":349,"o":"349-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge médico-chirurgicale d'un abcès et d'un panaris","q":"Quelles sont les spécificités du traitement chirurgical de l'abcès et du panaris pulpaire ?","a":"<p>Les spécificités incluent :</p><ul><li>Pour l'<strong>abcès</strong> : <strong>mise à plat et drainage</strong>. Une antibiothérapie probabiliste est donnée après la chirurgie, car sans drainage, les antibiotiques ne diffusent pas dans l'abcès.</li><li>Pour le <strong>panaris pulpaire</strong> : <strong>incisions pulpaires en Zig-Zag de Bruner</strong>. Il faut absolument <strong>éviter l'ouverture « en gueule de requin »</strong> qui compromet la vascularisation pulpaire.</li><li>Chez l'<strong>enfant</strong>, un panaris est une urgence car la matrice unguéale peut être détruite en <strong>48 heures</strong>.</li></ul>"},{"i":"33e118095ae4","n":349,"o":"349-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge médico-chirurgicale d'un phlegmon des gaines","q":"Quelle est la règle thérapeutique fondamentale face à un phlegmon des gaines ?","a":"<p>Un phlegmon des gaines constitue une <strong>urgence chirurgicale systématique</strong>. Le traitement chirurgical est indiqué à tous les stades.</p>"},{"i":"5899fde5a8e2","n":349,"o":"349-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge médico-chirurgicale d'un phlegmon des gaines","q":"Quelle est la prise en charge post-opératoire et l'antibiothérapie probabiliste d'un phlegmon des gaines ?","a":"<ul><li><strong>Prise en charge post-opératoire</strong> : une <strong>attelle</strong> maintenant les doigts en position intrinsèque plus (flexion MCP, extension des interphalangiennes).</li><li><strong>Antibiothérapie probabiliste (après prélèvements)</strong> :<ul><li><strong>Cas général</strong> : <strong>amoxicilline-acide clavulanique</strong> pendant 7 jours.</li><li><strong>En cas de morsure</strong> (risque de pasteurellose) : <strong>cyclines</strong> pendant 10 jours.</li></ul></li></ul><p>L'antibiothérapie est ensuite adaptée aux germes documentés.</p>"},{"i":"75357d03a373","n":349,"o":"349-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge médico-chirurgicale d'un phlegmon des gaines","q":"Comment la stratégie chirurgicale du phlegmon des gaines est-elle adaptée en fonction du stade anatomique ?","a":"<ul><li><strong>Stade 1 (ténosynovite inflammatoire)</strong> : <strong>lavage de la gaine</strong> par ses extrémités.</li><li><strong>Stade 2 (ténosynovite purulente)</strong> : <strong>lavage et synovectomie complète</strong>.</li><li><strong>Stade 3 (ténosynovite nécrosante)</strong> : <strong>excision de tous les tissus nécrotiques</strong> (chirurgie de sauvetage), avec des séquelles fonctionnelles constantes.</li></ul>"},{"i":"ddac4377a4e6","n":349,"o":"349-13","u":"Prise en charge","t":"Connaître les principes de la prise en charge médico-chirurgicale d'un phlegmon des gaines","q":"Quelles sont les mesures associées importantes dans la prise en charge d'un phlegmon des gaines et quel est le pronostic ?","a":"<ul><li><strong>Mesures associées</strong> : traitement de la porte d'entrée, <strong>SAT-VAT</strong>, prévention rabique si morsure, arrêt de travail, éducation, <strong>rééducation-kinésithérapie</strong> (lutte contre l'enraidissement).</li><li><strong>Pronostic</strong> : évolution favorable dans la majorité des cas sous traitement bien conduit, mais risque de <strong>séquelles fonctionnelles si le traitement est tardif</strong> (stade 2 ou 3), d'où l'importance de l'urgence diagnostique et chirurgicale.</li></ul>"},{"i":"2ce0a9666e45","n":349,"o":"349-2","u":"Définition","t":"Connaître la définition d'un abcès, d'un panaris, d'un phlegmon des gaines et de la main","q":"Quelle est la définition générale d'un phlegmon, et en quoi diffère-t-il d'un abcès ?","a":"<p>Un phlegmon (général) est une <strong>infection diffuse du tissu conjonctif</strong> caractérisée par l'absence de collection purulente organisée. Il se distingue de l'abcès, qui est une collection organisée dans une cavité néoformée. Un phlegmon peut potentiellement se propager rapidement dans les gaines synoviales.</p>"},{"i":"38c74d2f02e5","n":349,"o":"349-2","u":"Définition","t":"Connaître la définition d'un abcès, d'un panaris, d'un phlegmon des gaines et de la main","q":"Quelle est la définition d'un abcès dans le contexte des infections aiguës des parties molles ?","a":"<p>Un abcès est une <strong>collection de pus</strong> située dans une <strong>cavité néoformée</strong>. Il est délimité par une <strong>membrane pyogénique</strong>, ce qui en fait une poche circonscrite résultant de l'extension d'une infection.</p>"},{"i":"a258838d5ca7","n":349,"o":"349-2","u":"Définition","t":"Connaître la définition d'un abcès, d'un panaris, d'un phlegmon des gaines et de la main","q":"Comment définit-on un phlegmon des gaines dans le cadre des infections aiguës des parties molles ?","a":"<p>Un phlegmon des gaines est une <strong>infection de la gaine synoviale des fléchisseurs</strong> (ténosynovite), souvent comparée à une « péritonite du doigt ». Contrairement à l'abcès, il se caractérise par la présence de <strong>liquide dans la gaine</strong>, qui est une cavité préexistante et non néoformée.</p>"},{"i":"fa069942d334","n":349,"o":"349-2","u":"Définition","t":"Connaître la définition d'un abcès, d'un panaris, d'un phlegmon des gaines et de la main","q":"Qu'est-ce qu'un panaris selon la définition des infections aiguës des parties molles ?","a":"<p>Le panaris est une <strong>infection aiguë superficielle des parties molles d'un doigt</strong>. C'est un terme général désignant une « infection du doigt », souvent réduit en pratique au périonyxis (infection péri-unguéale).</p>"},{"i":"36e1cac68f57","n":349,"o":"349-3","u":"Épidémiologie","t":"Connaître la bactérie la plus souvent responsable","q":"Quels sont les germes prédominants dans les infections aiguës des parties molles ?","a":"<p>Les deux germes dominants sont :</p><ul><li>Le <strong>Staphylococcus aureus</strong> (environ 50 %).</li><li>Les <strong>Streptocoques</strong> (environ 10 %), principalement <strong>Streptococcus pyogenes</strong> (SGA β-hémolytique).</li></ul>"},{"i":"7d21fbdd53e6","n":349,"o":"349-3","u":"Épidémiologie","t":"Connaître la bactérie la plus souvent responsable","q":"Quelle bactérie est responsable de nécrose purulente cutanée en association avec une leucocidine spécifique, dans le cadre d'une infection aiguë des parties molles ?","a":"<p>Certaines souches de <strong>Staphylococcus aureus</strong>, notamment celles produisant la <strong>leucocidine de Panton-Valentine</strong>, peuvent entraîner une nécrose purulente cutanée, parfois associée à une pneumopathie nécrosante.</p>"},{"i":"860828beab00","n":349,"o":"349-3","u":"Épidémiologie","t":"Connaître la bactérie la plus souvent responsable","q":"Quel streptocoque est particulièrement impliqué dans les infections aiguës des parties molles et comment se caractérise-t-il sur le plan thérapeutique ?","a":"<p>Le <strong>Streptococcus pyogenes</strong> (SGA β-hémolytique) est un streptocoque souvent en cause. Il est <strong>toujours sensible à l'amoxicilline</strong>. Ses toxines (hyaluronidase, streptokinase) peuvent provoquer une nécrose tissulaire rapide.</p>"},{"i":"c64147b8a7b7","n":349,"o":"349-3","u":"Épidémiologie","t":"Connaître la bactérie la plus souvent responsable","q":"Quelle est la bactérie la plus fréquemment responsable des infections aiguës des parties molles, quel que soit le tableau clinique ?","a":"<p>La bactérie la plus souvent isolée est le <strong>Staphylococcus aureus</strong>, représentant environ <strong>50 %</strong> des cas. Il est à l'origine de tableaux cliniques variés.</p>"},{"i":"08ed8730156b","n":349,"o":"349-8","u":"Diagnostic positif","t":"Connaître les complications les plus fréquentes","q":"Quelles sont les complications spécifiques de l'abcès sous-cutané ?","a":"<p>Les complications spécifiques de l'abcès sous-cutané sont :</p><ul><li>La <strong>nécrose de la peau pulpaire</strong>.</li><li>L'<strong>extension aux tissus plus profonds</strong>, pouvant entraîner un <strong>phlegmon des gaines</strong>, une <strong>arthrite</strong> ou une <strong>ostéite</strong>.</li></ul>"},{"i":"40080a8a9768","n":349,"o":"349-8","u":"Diagnostic positif","t":"Connaître les complications les plus fréquentes","q":"Quelles sont les complications locales des infections aiguës des parties molles, selon la profondeur de diffusion ?","a":"<p>En cas de diffusion locale profonde, les complications peuvent inclure :</p><ul><li>La <strong>cellulite</strong>.</li><li>Le <strong>phlegmon</strong>.</li><li>L'<strong>arthrite</strong>.</li><li>L'<strong>ostéite</strong>.</li></ul>"},{"i":"894509334bf6","n":349,"o":"349-8","u":"Diagnostic positif","t":"Connaître les complications les plus fréquentes","q":"Quelles sont les complications spécifiques du périonyxis (paronychie) ?","a":"<p>Les complications spécifiques du périonyxis sont :</p><ul><li>L'<strong>abcès pulpaire</strong>.</li><li>Le <strong>phlegmon</strong>.</li><li>Le <strong>panaris « en bouton de chemise »</strong>.</li></ul>"},{"i":"9cdfa6a1a462","n":349,"o":"349-8","u":"Diagnostic positif","t":"Connaître les complications les plus fréquentes","q":"Quelles sont les complications générales des infections aiguës des parties molles ?","a":"<p>Les complications générales des infections aiguës des parties molles incluent :</p><ul><li>La <strong>bactériémie</strong>, se manifestant par de la <strong>fièvre</strong> et des <strong>frissons</strong>.</li><li>La <strong>dermo-hypodermite nécrosante</strong> (également appelée <strong>fasciite nécrosante</strong>), complication grave.</li></ul>"},{"i":"9e9b9918dc45","n":349,"o":"349-8","u":"Diagnostic positif","t":"Connaître les complications les plus fréquentes","q":"Quelles sont les complications régionales des infections aiguës des parties molles ?","a":"<p>Les complications régionales des infections aiguës des parties molles sont :</p><ul><li>La <strong>lymphangite</strong>.</li><li>L'<strong>adénite</strong>, notamment <strong>épitrochléenne et axillaire</strong>.</li></ul>"},{"i":"b6c8f998bb71","n":349,"o":"349-8","u":"Diagnostic positif","t":"Connaître les complications les plus fréquentes","q":"Quelles sont les complications tardives des infections aiguës des parties molles, particulièrement importantes pour la main ?","a":"<p>Les complications tardives peuvent être :</p><ul><li>La <strong>dystrophie unguéale</strong>.</li><li>La <strong>raideur</strong>.</li><li>Les <strong>séquelles fonctionnelles</strong>.</li><li>Les <strong>récidives</strong>.</li></ul><p>L'enjeu d'un diagnostic précoce est d'éviter ces séquelles, particulièrement graves pour la main, un outil indispensable.</p>"},{"i":"258f0d6d148e","n":349,"o":"349-9","u":"Diagnostic positif","t":"Savoir reconnaître un abcès ou un panaris","q":"Quelles sont les formes cliniques particulières de panaris ?","a":"<p>Les principales formes cliniques de panaris sont :<br/><ul><li><strong>Périonyxis (paronychie / panaris sous-unguéal)</strong> : autour de l'ongle, souvent lié à l'onychophagie ou la manucure, causé par le <strong>staphylocoque doré</strong>.</li><li><strong>Panaris anthracoïde</strong> : furoncle d'un poil digital (dos de P1), nécessite une <strong>excision obligatoire</strong>.</li><li><strong>Panaris « en bouton de chemise »</strong> : bipolaire, péri-unguéal communiquant à la pulpe par un pertuis, ne doit pas être méconnu (risque d'incision incomplète).</li><li><strong>Panaris sous-cutané (cellulite)</strong> : érythème diffus, pulpe inflammatoire souple (pas tendue), absence d'abcès initial.</li></ul></p>"},{"i":"70cee6b7fc1c","n":349,"o":"349-9","u":"Diagnostic positif","t":"Savoir reconnaître un abcès ou un panaris","q":"Comment reconnaît-on un abcès sous-cutané ou un abcès profond ?","a":"<p>La reconnaissance se fait comme suit :<br/><ul><li><strong>Abcès sous-cutané</strong> : survient dans le cadre d'une cellulite, avec en son centre une <strong>collection</strong>. Il se manifeste par une zone érythémateuse indurée et chaude, une tuméfaction rénitente, molle, <strong>fluctuante</strong>. Une porte d'entrée est souvent retrouvée. Une ponction est possible.</li><li><strong>Abcès profond (espaces de la main)</strong> : affecte les éminences thénar / hypothénar / médio-palmaire / interdigital. Il est difficile à distinguer de l'abcès sous-cutané et nécessite une <strong>échographie</strong> pour confirmation.</li><li><strong>Panaris pulpaire</strong> : est un abcès de la pulpe, caractérisé par un doigt <strong>pulsatile et tendu</strong> (à la différence du panaris sous-cutané où la pulpe est souple).</li></ul></p>"},{"i":"acc02634fce2","n":349,"o":"349-9","u":"Diagnostic positif","t":"Savoir reconnaître un abcès ou un panaris","q":"Comment distinguer cliniquement un panaris phlegmasique d'un panaris collecté ?","a":"<p>La distinction est essentielle pour l'orientation thérapeutique (médical vs chirurgical).<br/><ul><li><strong>Panaris phlegmasique (non collecté) :</strong> douleur modérée, diurne, sensation de cuisson ; tuméfaction érythémateuse à limites floues ; <strong>pas de collection, pas de pulsatilité</strong>, apyrexie.</li><li><strong>Panaris collecté :</strong> douleur intense, lancinante, <strong>PULSATILE, insomniante</strong> ; petite masse rénitente (collection sous tension) ; signes inflammatoires ± diffusion régionale.</li></ul></p>"},{"i":"c723bb3d86f5","n":349,"o":"349-9","u":"Diagnostic positif","t":"Savoir reconnaître un abcès ou un panaris","q":"Quels sont les pièges diagnostiques importants à connaître concernant les panaris ?","a":"<p>Il convient d'être vigilant face à plusieurs pièges diagnostiques :<br/><ul><li><strong>Panaris abâtardi par les ATB</strong> : les signes cliniques sont amoindris par les antibiotiques, mais le processus infectieux persiste, avec un risque de destructions osseuses ou de début de phlegmon.</li><li><strong>Panaris herpétique</strong> : caractérisé par des vésicules survenant vers <strong>J14</strong> et ayant tendance à <strong>récidiver au même endroit</strong>. La chirurgie est <strong>contre-indiquée</strong>, et le traitement repose sur le <strong>valaciclovir</strong>.</li><li><strong>Faux panaris d'Osler</strong> : se présente sous forme de nodosités bleuâtres fugaces. Il doit faire rechercher une <strong>endocardite</strong>.</li></ul></p>"}]};